import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DoubleSide, Vector2 } = ctx.THREE;

  // Container for the node
  const container = new Group();

  // Calculate plane size based on atlas region aspect ratio
  // Atlas region: width 512, height 320 => aspect 1.6
  const REGION_WIDTH = 512;
  const REGION_HEIGHT = 320;
  const aspect = REGION_WIDTH / REGION_HEIGHT;
  const planeWidth = aspect; // 1 unit height
  const planeHeight = 1;

  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    side: DoubleSide,
    transparent: true,
    depthWrite: false,
  });

  const mesh = new Mesh(geometry, material);
  container.add(mesh);

  // Billboard: always face the camera
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.lookAt(camera.position);
  };

  // Load texture asynchronously
  let loadedTexture = null;
  const texPromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;

      // Optional: set UV offset/repeat if atlas is larger than region.
      // Assume full texture corresponds to the region; otherwise adapt here.
    })
    .catch(() => {
      // texture failed – keep material empty
    });

  // Text handling (headline)
  const textItems = config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const textGroup = new Group();
  for (const item of textItems) {
    if (!item.text) continue;
    const textObj = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: ctx.primitives['kinetic-text']?.defaultColor ?? '#e8ecf2',
      align: 'center',
    });
    // Position the text slightly above the plane surface
    textObj.position.set(0, 0, 0.01);
    textGroup.add(textObj);
  }
  if (textGroup.children.length) {
    container.add(textGroup);
  }

  // No cinematic primitives for this node
  const primitiveHandlers = [];

  // User data for handlers (none) and cleanup
  container.userData.handlers = {};
  container.userData.cleanup = () => {
    // Dispose texture
    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }
    // Dispose material and geometry
    material.dispose();
    geometry.dispose();

    // Kill any GSAP timelines (none in this node, but safe)
    gsap.globalTimeline.getChildren().forEach((t) => t.kill());

    // Cleanup primitives if any were added in future extensions
    primitiveHandlers.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });

    // Remove mesh from container
    container.remove(mesh);
    mesh.onBeforeRender = null;
  };

  return container;
}
